    "selected_doc_ids": "[\"hotpotqa_67_doc_7\", \"hotpotqa_67_doc_9\", \"hotpotqa_67_doc_1\", \"hotpotqa_67_doc_3\", \"hotpotqa_67_doc_2\", \"hotpotqa_67_doc_0\", \"hotpotqa_67_doc_4\", \"hotpotqa_66_doc_6\", \"hotpotqa_66_doc_0\", \"hotpotqa_67_doc_6\"]",
