    "selected_doc_ids": "[\"hotpotqa_22_doc_9\", \"hotpotqa_22_doc_3\", \"hotpotqa_22_doc_6\", \"hotpotqa_22_doc_8\", \"hotpotqa_1_doc_8\", \"hotpotqa_22_doc_5\", \"hotpotqa_22_doc_1\", \"hotpotqa_22_doc_7\", \"hotpotqa_122_doc_9\", \"hotpotqa_20_doc_4\"]",
