    "selected_doc_ids": "[\"hotpotqa_62_doc_4\", \"hotpotqa_62_doc_9\", \"hotpotqa_62_doc_0\", \"hotpotqa_62_doc_3\", \"hotpotqa_62_doc_2\", \"hotpotqa_62_doc_5\", \"hotpotqa_62_doc_1\", \"hotpotqa_140_doc_4\", \"hotpotqa_25_doc_7\", \"hotpotqa_62_doc_6\"]",
