    "selected_doc_ids": "[\"hotpotqa_149_doc_0\", \"hotpotqa_149_doc_7\", \"hotpotqa_149_doc_8\", \"hotpotqa_149_doc_5\", \"hotpotqa_149_doc_4\", \"hotpotqa_149_doc_6\", \"hotpotqa_149_doc_2\", \"hotpotqa_149_doc_1\", \"hotpotqa_149_doc_3\", \"hotpotqa_73_doc_6\"]",
