    "selected_doc_ids": "[\"hotpotqa_80_doc_4\", \"hotpotqa_80_doc_5\", \"hotpotqa_80_doc_8\", \"hotpotqa_80_doc_7\", \"hotpotqa_80_doc_3\", \"hotpotqa_80_doc_2\", \"hotpotqa_80_doc_9\", \"hotpotqa_80_doc_1\", \"hotpotqa_80_doc_0\", \"hotpotqa_80_doc_6\"]",
